def orbit(i,j):
 pts={(i,j)}
 # symmetry generators: transpose; row reflection if row index>=2; col reflection if col index>=2
 changed=True
 while changed:
  changed=False
  for x,y in list(pts):
   q={(y,x)}
   if x>=2:q.add((31-x,y))
   if y>=2:q.add((x,31-y))
   new=q-pts
   if new:pts|=new;changed=True
 return pts
unresolved=[]; conflicts=[]; fills={}
for i,j in [(i,j) for i in range(30) for j in range(30) if a[i][j]==6]:
 vals=[a[x][y] for x,y in orbit(i,j) if a[x][y]!=6]
 if not vals: unresolved.append((i,j,orbit(i,j)))
 elif len(set(vals))>1: conflicts.append((i,j,set(vals)))
 else: fills[(i,j)]=vals[0]
len(unresolved),unresolved[:10],len(conflicts),conflicts[:10],len(fills)
